"""Generated by OpenAI Codex on 2026-11-03. Import/link normalization and permission boundaries."""

import copy
import os

os.environ.setdefault("DATABASE_URL", "sqlite://")
import pytest
from fastapi.testclient import TestClient
from api.main import app
from api.routers.auth.auth import require_user
from services.campus_map import (
    geometries,
    normalize_links,
    parse_osm,
    stable_id,
    validate_graph,
)

SOURCE = b"""<osm version="0.6"><node id="1" lat="43" lon="-84"><tag k="entrance" v="main"/><tag k="entrance:building" v="Library"/></node><node id="2" lat="43" lon="-84.001"/><node id="3" lat="43.001" lon="-84.001"/><way id="4"><nd ref="1"/><nd ref="2"/><nd ref="3"/><nd ref="1"/><tag k="building" v="yes"/><tag k="name" v="Park Library"/><tag k="alt_name" v="Library;Park"/></way><node id="5" lat="43" lon="-84.002"><tag k="amenity" v="bicycle_parking"/><tag k="capacity" v="12"/></node><way id="6"><nd ref="1"/><nd ref="2"/><tag k="highway" v="footway"/></way><way id="7"><nd ref="1"/><nd ref="2"/><nd ref="3"/><nd ref="1"/><tag k="amenity" v="parking"/></way></osm>"""


def test_import_preserves_types_tags_and_links_by_stable_id():
    graph = parse_osm(SOURCE)
    normalize_links(graph)
    assert len(graph) == 7
    entrance = graph[stable_id("node", 1)]
    assert entrance["building_id"] == stable_id("way", 4)
    assert "entrance:building" not in entrance["tags"]
    assert entrance["source_tags"]["entrance:building"] == "Library"
    assert graph[stable_id("node", 5)]["tags"]["capacity"] == "12"
    assert graph[stable_id("way", 7)]["tags"]["amenity"] == "parking"
    assert graph[stable_id("way", 6)]["refs"][0]["id"] == stable_id("node", 1)
    graph[stable_id("way", 4)]["tags"]["name"] = "Renamed library"
    normalize_links(graph)
    assert entrance["building_id"] == stable_id("way", 4)


def test_ambiguous_names_and_conflicting_outlines_need_review():
    graph = parse_osm(SOURCE)
    entrance = graph[stable_id("node", 1)]
    entrance["tags"]["entrance:building"] = "Wrong name"
    normalize_links(graph)
    assert entrance["building_id"] is None
    assert entrance["link_status"] == "unlinked"
    entrance["tags"].pop("entrance:building")
    duplicate = copy.deepcopy(graph[stable_id("way", 4)])
    duplicate["id"] = stable_id("way", 99)
    graph[duplicate["id"]] = duplicate
    normalize_links(graph)
    assert entrance["link_status"] == "ambiguous"


def test_geometry_and_reference_validation():
    graph = parse_osm(SOURCE)
    geometry, status = geometries(graph)
    assert geometry[stable_id("way", 4)].geom_type == "Polygon"
    assert geometry[stable_id("way", 6)].geom_type == "LineString"
    assert geometry[stable_id("node", 5)].geom_type == "Point"
    changed = copy.deepcopy(graph)
    del changed[stable_id("node", 1)]
    with pytest.raises(ValueError, match="broken"):
        validate_graph(changed, graph)
    graph[stable_id("node", 1)]["position"] = [float("nan"), 0]
    with pytest.raises(ValueError, match="coordinates"):
        validate_graph(graph)


