def test_backend_enforces_email_permissions(client):
    assert client.get("/api/map/permissions").json() == {"can_edit": False}
    assert client.get("/api/map/editor").status_code == 403
    assert (
        client.post(
            "/api/map/editor",
            json={
                "revision": 1,
                "upserts": [],
                "deletes": [],
                "email": "tufts1cr@cmich.edu",
            },
        ).status_code
        == 403
    )
    app.dependency_overrides[require_user] = lambda: {
        "sub": "test",
        "email": "tufts1cr@cmich.edu",
    }
    assert client.get("/api/map/permissions").json() == {"can_edit": True}
    app.dependency_overrides[require_user] = lambda: {
        "sub": "test",
        "email": "developer@example.test",
    }
    assert client.get("/api/map/permissions").json() == {"can_edit": False}


def test_anonymous_requests_are_rejected(monkeypatch):
    monkeypatch.setenv("AUTH_REQUIRED", "1")
    with TestClient(app) as client:
        assert client.get("/api/map/features").status_code == 401
        assert client.get("/api/map/editor").status_code == 401


def test_local_editor_rejects_foreign_origin(monkeypatch):
    monkeypatch.setenv("AUTH_REQUIRED", "0")
    with TestClient(app) as client:
        assert client.get("/api/map/permissions").json() == {"can_edit": True}
        assert (
            client.post(
                "/api/map/editor",
                headers={"origin": "https://evil.example"},
                json={"revision": 1, "upserts": [], "deletes": []},
            ).status_code
            == 403
        )
